package claudecode

import "testing"

func TestUnsupportedMessage(t *testing.T) {
	for _, c := range []struct {
		goos, goarch, want string
	}{
		{"windows", "amd64", "Kogen's Claude Code runtime supports macOS on Apple Silicon and Linux x86-64 only, not windows/amd64"},
		{"darwin", "arm64", "Kogen's Claude Code runtime supports macOS on Apple Silicon and Linux x86-64 only, not darwin/arm64"},
		{"linux", "amd64", "Kogen's Claude Code runtime supports macOS on Apple Silicon and Linux x86-64 only, not linux/amd64"},
	} {
		t.Run(c.goos+"/"+c.goarch, func(t *testing.T) {
			if got := UnsupportedMessage(c.goos, c.goarch); got != c.want {
				t.Errorf("UnsupportedMessage(%q, %q) = %q, want %q", c.goos, c.goarch, got, c.want)
			}
		})
	}
}

func TestFirstField(t *testing.T) {
	for _, tc := range []struct{ name, answer, want string }{
		{"empty", "", ""},
		{"whitespace", " \t\n", ""},
		{"metadata", " \t2.1.300 (Claude Code)\n", "2.1.300"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if got := FirstField(tc.answer); got != tc.want {
				t.Errorf("FirstField(%q) = %q, want %q", tc.answer, got, tc.want)
			}
		})
	}
}

func TestPinned(t *testing.T) {
	for _, tc := range []struct {
		name, answer string
		want         bool
	}{
		{"metadata", " \t" + Version + " (Claude Code)\n", true},
		{"empty", "", false},
		{"different", Version + "0 (Claude Code)", false},
		{"suffix", Version + "-beta (Claude Code)", false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if got := Pinned(tc.answer); got != tc.want {
				t.Errorf("Pinned(%q) = %t, want %t", tc.answer, got, tc.want)
			}
		})
	}
}

func TestNotPinnedMessage(t *testing.T) {
	const path = "/x/claude"
	const answer = Version + "-beta (Claude Code)"
	for _, tc := range []struct{ name, expectedVersion, want string }{
		{"pinned", Version, "Kogen's Claude Code at /x/claude reports " + Version + "-beta (Claude Code), not the pinned " + Version},
		{"active", Version + "0", "Kogen's Claude Code at /x/claude reports " + Version + "-beta (Claude Code), not the active " + Version + "0"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			if got := NotPinnedMessage(path, answer, tc.expectedVersion); got != tc.want {
				t.Errorf("NotPinnedMessage(%q, %q, %q) = %q, want %q", path, answer, tc.expectedVersion, got, tc.want)
			}
		})
	}
}

